from pathlib import Path
import py_compile,shutil
ROOT=Path.cwd()
PKG=ROOT/'qseries_v2/oracle_strategy_intelligence/solana_money/mriya_python_paper_arb'
REQ=(PKG/'core.py',PKG/'scanner.py',ROOT/'qseries_v2/oracle_strategy_intelligence/solana_universal_trade_tape/usls_046b_shared_multidex_live_event_router.py',ROOT/'qseries_v2/oracle_strategy_intelligence/solana_universal_trade_tape/usls_047c_batched_retry_safe_multidex_identity_resolver.py')
for p in REQ:
    if not p.is_file(): raise SystemExit('[FAIL] missing certified dependency: '+str(p.relative_to(ROOT)))
backup=ROOT/'runtime_state/qseries/qsb038d_backup';backup.mkdir(parents=True,exist_ok=True)
for n in ('crosslisted.py','runtime_crosslisted.py'):
    p=PKG/n
    if p.exists(): shutil.copy2(p,backup/n)
(PKG/'crosslisted.py').write_text('from __future__ import annotations\nimport asyncio,json,os,time\nfrom collections import Counter\nfrom pathlib import Path\nfrom . import core\nfrom . import scanner as prior\n\nCAPTURE_SECONDS=5\nMAX_INTERSECTIONS=6\nSIZES_SOL=(0.03,0.05,0.10,0.20,0.35,0.50,0.75,1.00)\nMIN_NET_BPS=15.0\nMAX_SLOT_SPREAD=4\nTX_COST_SOL=0.0001\n\ndef _artifact(root,name):\n    return Path(root)/"runtime_state/solana_opportunities/universal_trade_tape"/name\n\ndef live_pumpswap_identities(root,capture_seconds=CAPTURE_SECONDS):\n    from qseries_v2.oracle_strategy_intelligence.solana_universal_trade_tape.usls_046b_shared_multidex_live_event_router import capture\n    from qseries_v2.oracle_strategy_intelligence.solana_universal_trade_tape.usls_047c_batched_retry_safe_multidex_identity_resolver import resolve\n    ret=asyncio.run(capture(seconds=int(capture_seconds),max_rows=1600))\n    rows=list(ret.get("rows") or [])\n    base=_artifact(root,"multidex_live_event_router.json")\n    base.parent.mkdir(parents=True,exist_ok=True)\n    base.write_text(json.dumps(ret,indent=2),encoding="utf-8")\n    active=Counter()\n    for r in rows:\n        if r.get("venue")!="PUMP_SWAP":continue\n        ev=r.get("event") or {}\n        pool=ev.get("pool") or r.get("pool") or r.get("market_address")\n        if pool:active[str(pool)]+=1\n    if not active:\n        return {"router_rows":len(rows),"active_pools":0,"identities":[]}\n    resolved=resolve(Path(root))\n    ids=list((resolved or {}).get("rows") or (resolved or {}).get("identities") or [])\n    out=[]\n    for x in ids:\n        if x.get("venue")!="PUMP_SWAP" or x.get("identity_state")!="EXACT":continue\n        pool=str(x.get("pool") or "")\n        if pool not in active:continue\n        base_mint=str(x.get("base_mint") or "");quote_mint=str(x.get("quote_mint") or "")\n        if quote_mint==core.WSOL and base_mint and base_mint!=core.WSOL:\n            token=base_mint;token_dec=x.get("base_decimals");wsol_dec=x.get("quote_decimals")\n        elif base_mint==core.WSOL and quote_mint and quote_mint!=core.WSOL:\n            token=quote_mint;token_dec=x.get("quote_decimals");wsol_dec=x.get("base_decimals")\n        else:continue\n        out.append({"pump_pool":pool,"token":token,"token_decimals":int(token_dec),\n                    "wsol_decimals":int(wsol_dec),"activity":int(active[pool])})\n    out.sort(key=lambda z:z["activity"],reverse=True)\n    return {"router_rows":len(rows),"active_pools":len(active),"identities":out}\n\ndef _rows(j):\n    if isinstance(j,list):return j\n    if isinstance(j,dict):\n        for k in ("data","pools","items","results"):\n            if isinstance(j.get(k),list):return j[k]\n    return []\n\ndef _mint(o):\n    if isinstance(o,str):return o\n    if isinstance(o,dict):\n        for k in ("address","mint","token_address"):\n            if isinstance(o.get(k),str):return o[k]\n    return ""\n\ndef _dec(o):\n    if isinstance(o,dict):\n        for k in ("decimals","decimal"):\n            try:return int(o[k])\n            except Exception:pass\n    return None\n\ndef meteora_matches(token,http=core.http_json):\n    j=http(f"{core.METEORA_API}/pools?page=1&page_size=100&query={token}")\n    found=[]\n    for x in _rows(j):\n        tx=x.get("token_x") or x.get("tokenX") or {}\n        ty=x.get("token_y") or x.get("tokenY") or {}\n        mx,my=_mint(tx),_mint(ty)\n        if {mx,my}!={core.WSOL,token}:continue\n        addr=x.get("address") or x.get("pool_address") or x.get("pubkey")\n        dx,dy=_dec(tx),_dec(ty)\n        if not addr or dx is None or dy is None:continue\n        score=0.0\n        for k in ("tvl","liquidity","liquidity_usd"):\n            try:score=max(score,float(x.get(k) or 0))\n            except Exception:pass\n        found.append({"address":str(addr),"token_x":mx,"token_y":my,\n                      "decimals_x":dx,"decimals_y":dy,"token":token,"score":score})\n    found.sort(key=lambda z:z["score"],reverse=True)\n    return found\n\ndef crosslisted(root,http=core.http_json,capture_seconds=CAPTURE_SECONDS,max_intersections=MAX_INTERSECTIONS):\n    p=live_pumpswap_identities(root,capture_seconds)\n    pairs=[]\n    seen=set()\n    for ident in p["identities"]:\n        tok=ident["token"]\n        if tok in seen:continue\n        seen.add(tok)\n        try:ms=meteora_matches(tok,http)\n        except Exception:continue\n        if not ms:continue\n        pairs.append({"token":tok,"pump_pool":ident["pump_pool"],"pump_activity":ident["activity"],\n                      "meteora":ms[0]})\n        if len(pairs)>=int(max_intersections):break\n    return p,pairs\n\ndef optimize_pair(root,pair,http=core.http_json,rpc_fn=core.rpc):\n    rpc_url=os.getenv("SOLANA_RPC_URL",core.DEFAULT_RPC)\n    meta=pair["meteora"]\n    # Hydrate only after cross-list is proven.\n    state=prior.pool_state(rpc_url,meta)\n    best=None;all_rows=[]\n    for size in SIZES_SOL:\n        for fn in (prior.direction_a,prior.direction_b):\n            try:\n                x=fn(rpc_url,state,meta,size,http,rpc_fn)\n                x["pump_pool"]=pair["pump_pool"];x["pump_activity"]=pair["pump_activity"]\n                all_rows.append(x)\n                if best is None or x["net_bps"]>best["net_bps"]:best=x\n            except Exception as e:\n                all_rows.append({"direction":fn.__name__,"token":pair["token"],"pool":meta["address"],\n                                 "pump_pool":pair["pump_pool"],"start_sol":size,\n                                 "error":f"{type(e).__name__}: {e}","paper_trade":False})\n    return best,all_rows\n\ndef scan(root,http=core.http_json,rpc_fn=core.rpc,capture_seconds=CAPTURE_SECONDS,max_intersections=MAX_INTERSECTIONS):\n    pump,pairs=crosslisted(root,http,capture_seconds,max_intersections)\n    print("[LIVE_PUMPSWAP] router_rows=%d active_pools=%d exact_wsol_identities=%d"%(\n      pump["router_rows"],pump["active_pools"],len(pump["identities"])),flush=True)\n    print("[CROSSLIST] pump_meteora_pairs=%d"%len(pairs),flush=True)\n    results=[];best=None\n    for i,pair in enumerate(pairs,1):\n        print("[PAIR %d/%d] token=%s pump_pool=%s meteora_pool=%s pump_activity=%d"%(\n          i,len(pairs),pair["token"],pair["pump_pool"],pair["meteora"]["address"],pair["pump_activity"]),flush=True)\n        try:b,rows=optimize_pair(root,pair,http,rpc_fn)\n        except Exception as e:\n            print("[PAIR_ERROR] token=%s %s: %s"%(pair["token"],type(e).__name__,e),flush=True)\n            continue\n        results.extend(rows)\n        if b:\n            print("[PAIR_BEST] dir=%s size=%.6f end=%.9f net=%+.9f bps=%+.2f fresh=%s PAPER_TRADE=%s"%(\n              b["direction"],b["start_sol"],b["end_sol"],b["net_sol"],b["net_bps"],b["fresh"],\n              "YES" if b["paper_trade"] else "NO"),flush=True)\n            if best is None or b["net_bps"]>best["net_bps"]:best=b\n        time.sleep(.35)\n    out={"revision":"QSB_038D","live_pumpswap":pump,"crosslisted_pairs":pairs,\n         "quotes":results,"best":best,"execution_authority":False}\n    rp=Path(root)/"runtime_state/qseries/qsb038d_crosslisted_atomic_arb/report.json"\n    rp.parent.mkdir(parents=True,exist_ok=True);rp.write_text(json.dumps(out,indent=2),encoding="utf-8")\n    return out\n',encoding='utf-8')
(PKG/'runtime_crosslisted.py').write_text('from pathlib import Path\nfrom .core import ensure_meteora_math\nfrom .crosslisted import scan\n\ndef main():\n    print("[QSB-038D] CROSS-LISTED LIVE ATOMIC ARB SCANNER",flush=True)\n    print("[ORDER] live PumpSwap activity FIRST -> exact Pump identities -> Meteora intersection -> quote both directions",flush=True)\n    print("[NO FISHING] does not scan random/high-TVL Meteora tokens",flush=True)\n    print("[SIZE_GRID] 0.03,0.05,0.10,0.20,0.35,0.50,0.75,1.00 SOL",flush=True)\n    print("[MODE] PAPER_ONLY=True execution_authority=FALSE",flush=True)\n    dep=ensure_meteora_math();print("[PYTHON_QUOTE_MATH]",dep,flush=True)\n    if not dep.get("ok"):return\n    r=scan(Path.cwd())\n    b=r.get("best")\n    if b:\n        print("[BEST] token=%s dir=%s pump_pool=%s meteora_pool=%s start=%.6f end=%.9f net=%+.9f bps=%+.2f fresh=%s PAPER_TRADE=%s"%(\n          b["token"],b["direction"],b.get("pump_pool"),b["pool"],b["start_sol"],b["end_sol"],\n          b["net_sol"],b["net_bps"],b["fresh"],"YES" if b["paper_trade"] else "NO"),flush=True)\n    else:\n        print("[BEST] NONE",flush=True)\n    print("[SUMMARY] crosslisted=%d quotes=%d execution_authority=FALSE"%(\n      len(r["crosslisted_pairs"]),len(r["quotes"])),flush=True)\n\nif __name__=="__main__":main()\n',encoding='utf-8')
(ROOT/'test_qsb_038d_crosslisted_atomic_arb_scanner.py').write_text('import unittest,tempfile\nfrom unittest.mock import patch\nfrom pathlib import Path\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.mriya_python_paper_arb import core\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.mriya_python_paper_arb import crosslisted as x\n\nclass T(unittest.TestCase):\n    def test_intersection_starts_from_pumpswap_not_meteora(self):\n        pump={"router_rows":50,"active_pools":2,"identities":[\n          {"pump_pool":"PP1","token":"TOK1","token_decimals":6,"wsol_decimals":9,"activity":5},\n          {"pump_pool":"PP2","token":"TOK2","token_decimals":6,"wsol_decimals":9,"activity":2}]}\n        with patch.object(x,"live_pumpswap_identities",return_value=pump):\n            def h(url,*a,**k):\n                tok="TOK1" if "TOK1" in url else "TOK2"\n                return {"data":[{"address":"M-"+tok,"token_x":{"address":core.WSOL,"decimals":9},\n                                 "token_y":{"address":tok,"decimals":6},"tvl":100}]}\n            p,pairs=x.crosslisted(".",h,1,6)\n        self.assertEqual(len(pairs),2);self.assertEqual(pairs[0]["pump_pool"],"PP1")\n        print("[PASS] live PumpSwap exact identities are the discovery source; Meteora is only intersected afterward")\n\n    def test_non_crosslisted_token_never_hydrates(self):\n        pump={"router_rows":10,"active_pools":1,"identities":[\n          {"pump_pool":"PP","token":"NO_METEORA","token_decimals":6,"wsol_decimals":9,"activity":1}]}\n        with patch.object(x,"live_pumpswap_identities",return_value=pump):\n            p,pairs=x.crosslisted(".",lambda *a,**k:{"data":[]},1,6)\n        self.assertEqual(pairs,[])\n        print("[PASS] non-cross-listed Pump token is rejected before any Solana pool hydration")\n\n    def test_meteora_exact_pair_only(self):\n        def h(url,*a,**k):\n            return {"data":[\n              {"address":"BAD","token_x":{"address":"X","decimals":6},"token_y":{"address":"TOK","decimals":6},"tvl":999},\n              {"address":"GOOD","token_x":{"address":core.WSOL,"decimals":9},"token_y":{"address":"TOK","decimals":6},"tvl":5}]}\n        m=x.meteora_matches("TOK",h);self.assertEqual([r["address"] for r in m],["GOOD"])\n        print("[PASS] only exact WSOL/token Meteora pairs survive intersection")\n\n    def test_size_grid_has_small_fast_arb_sizes(self):\n        self.assertEqual(x.SIZES_SOL[0],.03);self.assertIn(.10,x.SIZES_SOL);self.assertIn(1.0,x.SIZES_SOL)\n        print("[PASS] optimizer tests small-to-1SOL sizes instead of reusing old Mriya sizes")\n\n    def test_profit_gate_is_inherited_fresh_and_net(self):\n        a=x.prior.evaluate(1,1.003,100,101,.0001)\n        stale=x.prior.evaluate(1,1.01,100,110,.0001)\n        self.assertTrue(a["paper_trade"]);self.assertFalse(stale["paper_trade"])\n        print("[PASS] positive edge must also be same-window fresh")\n\n    def test_live_capture_persist_contract(self):\n        import inspect\n        s=Path(inspect.getfile(x)).read_text(encoding="utf-8")\n        self.assertIn("capture(seconds=int(capture_seconds)",s)\n        self.assertIn("multidex_live_event_router.json",s)\n        self.assertIn("resolve(Path(root))",s)\n        print("[PASS] scanner refreshes certified live router then resolves exact PumpSwap pool identity")\n\nif __name__=="__main__":unittest.main(verbosity=2)\n',encoding='utf-8')
(ROOT/'run_qsb_038d_crosslisted_atomic_arb_scanner.py').write_text("from qseries_v2.oracle_strategy_intelligence.solana_money.mriya_python_paper_arb.runtime_crosslisted import main\nif __name__=='__main__':main()\n",encoding='utf-8')
